sql.where:
g.publish_status = 'published'

    AND (g.title LIKE CONCAT('%', #{keyword}, '%')
         OR g.summary LIKE CONCAT('%', #{keyword}, '%')
         OR g.content_html LIKE CONCAT('%', #{keyword}, '%'))


    AND g.scope = #{scope}


    AND g.travel_mode = #{travelMode}

mapper.select:
SELECT g.id, g.destination_id, g.author_id, g.title, g.summary, g.cover_image_url, g.location_text, g.scope, g.travel_mode, g.published_at, g.days, g.budget_total, g.views_count, g.likes_count, g.comments_count, g.favorites_count, g.status, d.name AS destination_name, up.nickname AS author_name, up.avatar_url AS author_avatar_url FROM guides g LEFT JOIN destinations d ON d.id = g.destination_id LEFT JOIN user_profiles up ON up.user_id = g.author_id
AND g.status = #{status}
ORDER BY g.published_at DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM guides g


        AND g.status = #{status}

SELECT COUNT(*)
FROM guides
WHERE author_id = #{authorId}

SELECT g.id, g.destination_id, g.author_id, g.title, g.summary, g.cover_image_url, g.location_text, g.scope, g.travel_mode, g.published_at, g.days, g.budget_total, g.views_count, g.likes_count, g.comments_count, g.favorites_count, g.status, d.name AS destination_name, up.nickname AS author_name, up.avatar_url AS author_avatar_url FROM guides g LEFT JOIN destinations d ON d.id = g.destination_id LEFT JOIN user_profiles up ON up.user_id = g.author_id WHERE g.id IN
#{id}
ORDER BY g.created_at DESC

mapper.update:
UPDATE guides SET title=#{title}, summary=#{summary}, content_html=#{contentHtml},
    cover_image_url=#{coverImageUrl}, location_text=#{locationText}, scope=#{scope}, travel_mode=#{travelMode}
WHERE id=#{id}

